window.VO = [{"id":"n01","text":"Sweden once made every driver on the road stop dead at ten to five on a September morning in 1967,","at":0.24,"t0":0.12,"t1":7.24},{"id":"n02","text":"because at five o'clock, the whole country would switch to driving on the right, like its neighbours.","at":14.92,"t0":7.46,"t1":12.6},{"id":"n03","text":"So when they all switched at once, did road deaths go up, or down?","at":26.1,"t0":13.05,"t1":16.57},{"id":"n04","text":"Drivers like Ingrid had driven on the left all their lives, and one slip of habit would put them head-on into someone.","at":35.14,"t0":17.57,"t1":24.15},{"id":"n05","text":"Deaths went down, by almost half, with speed limits cut.","at":57.1,"t0":28.55,"t1":31.67},{"id":"n06","text":"For two months, it looked as if the switch they called Dagen_H had made Sweden's roads safer overnight.","at":63.7,"t0":31.85,"t1":37.86},{"id":"n07","text":"But by November, with the limits still down, the deaths were back where they'd been, because once the road felt normal, the care wore off.","at":76.82,"t0":38.41,"t1":45.62},{"id":"n08","text":"So the safest Ingrid ever drove was the morning she was sure she'd crash.","at":92.04,"t0":46.02,"t1":50.43}];
